  console.log('\n' + '='.repeat(60))
  console.log('测试完成！')

  const allPassed = r2.success && r3.success && r4.success && r5.success &&
    r7.success && r8.success && r9.success && r10.success &&
    r11.success && r12.success && !r13.success && r14.success && r15.success && r16.success
  return allPassed
}

